package com.graden.editor.cinema;
import android.content.Context;import android.net.Uri;import android.graphics.*;import java.io.*;import java.util.*;import java.util.zip.*;import java.security.MessageDigest;
public final class ClipCache {
 private final File root;private File data;public final ArrayList<Long> times=new ArrayList<>();public final ArrayList<Integer> scenes=new ArrayList<>();
 public ClipCache(Context c,Uri uri)throws Exception{String key="stable-v3-npu:"+uri;try(android.database.Cursor q=c.getContentResolver().query(uri,new String[]{"_size","last_modified"},null,null,null)){if(q!=null&&q.moveToFirst())key+=":"+q.getString(0)+":"+q.getString(1);}catch(Exception ignored){}StringBuilder id=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(key.getBytes("UTF-8")))id.append(String.format("%02x",b&255));root=new File(c.getFilesDir(),"clips/"+id);root.mkdirs();data=new File(root,"complete");File index=new File(data,"index");if(index.exists())try(DataInputStream in=new DataInputStream(new BufferedInputStream(new FileInputStream(index)))){int n=in.readInt();if(n<1||n>10000000)throw new IOException("Invalid frame index");for(int i=0;i<n;i++){times.add(in.readLong());scenes.add(in.readInt());}}}
 public File edits(){return new File(root,"focus.json");}public boolean ready(){return !times.isEmpty()&&new File(data,"index").exists();}
 private static void remove(File f)throws IOException{if(!f.exists())return;if(f.isDirectory()){File[] list=f.listFiles();if(list!=null)for(File child:list)remove(child);}if(!f.delete())throw new IOException("Cannot remove cached file");}
 public void clear()throws Exception{remove(new File(root,"complete"));remove(new File(root,"building"));remove(new File(root,"previous"));times.clear();scenes.clear();data=new File(root,"complete");}
 public void begin()throws Exception{data=new File(root,"building");remove(data);if(!data.mkdirs())throw new IOException("Cannot create analysis folder");times.clear();scenes.clear();}
 private File path(int i,String ext){return new File(data,String.format(Locale.US,"%07d.%s",i,ext));}
 public synchronized int reserve(long t,int scene)throws Exception{if(root.getUsableSpace()<200000000)throw new IOException("Free more storage before analyzing this clip.");times.add(t);scenes.add(scene);return times.size()-1;}
 public void append(long t,Bitmap source,AiEngine.Maps m)throws Exception{write(reserve(t,m.scene),source,m);}
 /** Writes frame ix; several frames may be written at once. Same files, same bytes, as one at a time. */
 public void write(int ix,Bitmap source,AiEngine.Maps m)throws Exception{try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new DeflaterOutputStream(new FileOutputStream(path(ix,"maps")),new Deflater(1))))){out.writeInt(m.width);out.writeInt(m.height);short[] dv=new short[m.values.length];for(int k=0;k<dv.length;k++)dv[k]=(short)Math.round(m.values[k]*65535);byte[] db=new byte[dv.length*2];java.nio.ByteBuffer.wrap(db).asShortBuffer().put(dv);out.write(db);int w=m.foreground.getWidth(),h=m.foreground.getHeight();out.writeInt(w);out.writeInt(h);int[] px=new int[w*h];m.foreground.getPixels(px,0,w,0,0,w,h);for(int k=0;k<px.length;k++)if(px[k]>>>24==0)px[k]=0;byte[] pb=new byte[px.length*4];java.nio.ByteBuffer.wrap(pb).asIntBuffer().put(px);out.write(pb);}
 float ratio=Math.min(1,768f/Math.max(source.getWidth(),source.getHeight()));Bitmap thumb=Bitmap.createScaledBitmap(source,Math.max(2,Math.round(source.getWidth()*ratio)),Math.max(2,Math.round(source.getHeight()*ratio)),true);try(OutputStream out=new FileOutputStream(path(ix,"jpg"))){if(!thumb.compress(Bitmap.CompressFormat.JPEG,94,out))throw new IOException("Thumbnail write failed");}if(thumb!=source)thumb.recycle();
 int w=96,h=Math.max(24,96*source.getHeight()/source.getWidth());Bitmap small=Bitmap.createScaledBitmap(source,w,h,true);int[] rgb=new int[w*h];small.getPixels(rgb,0,w,0,0,w,h);if(small!=source)small.recycle();try(DataOutputStream o=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(path(ix,"track"))))){o.writeInt(w);o.writeInt(h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){float u=(x+.5f)/w,v=(y+.5f)/h;int p=rgb[y*w+x];o.writeByte(((p>>16&255)*77+(p>>8&255)*150+(p&255)*29)>>8);o.writeByte(m.foreground.getPixel(Math.min(m.foreground.getWidth()-1,(int)(u*m.foreground.getWidth())),Math.min(m.foreground.getHeight()-1,(int)(v*m.foreground.getHeight())))>>>24);o.writeShort(Math.round(m.at(u,v)*65535));}o.writeInt(m.boxes.length);for(float b:m.boxes)o.writeFloat(b);}
 }
 public void finish()throws Exception{if(times.isEmpty())throw new IOException("No video frames");try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(new File(data,"index"))))){out.writeInt(times.size());for(int i=0;i<times.size();i++){out.writeLong(times.get(i));out.writeInt(scenes.get(i));}}File old=new File(root,"previous"),complete=new File(root,"complete");remove(old);if(complete.exists()&&!complete.renameTo(old))throw new IOException("Cannot replace previous cache");if(!data.renameTo(complete)){old.renameTo(complete);throw new IOException("Cannot commit analysis");}data=complete;remove(old);}
 public int nearest(long t){int p=Collections.binarySearch(times,t);if(p>=0)return p;p=-p-1;if(p==0)return 0;if(p==times.size())return p-1;return t-times.get(p-1)<times.get(p)-t?p-1:p;}
 public Bitmap thumbnail(int i){return BitmapFactory.decodeFile(path(i,"jpg").getPath());}
 public AiEngine.Maps maps(int i)throws Exception{AiEngine.Maps m=new AiEngine.Maps();try(DataInputStream in=new DataInputStream(new BufferedInputStream(new InflaterInputStream(new FileInputStream(path(i,"maps")))))){m.width=in.readInt();m.height=in.readInt();int n=m.width*m.height;m.values=new float[n];int[] px=new int[n];for(int j=0;j<n;j++){m.values[j]=in.readUnsignedShort()/65535f;int q=Math.round(m.values[j]*255);px[j]=0xff000000|q<<16|q<<8|q;}m.depth=Bitmap.createBitmap(px,m.width,m.height,Bitmap.Config.ARGB_8888);int w=in.readInt(),h=in.readInt();px=new int[w*h];for(int j=0;j<px.length;j++)px[j]=in.readInt();m.foreground=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);m.foreground.setPremultiplied(false);m.foreground.setPixels(px,0,w,0,0,w,h);m.scene=scenes.get(i);m.cut=i==0||!scenes.get(i).equals(scenes.get(i-1));return m;}catch(Exception e){m.close();throw e;}}
 public static class Feature{public int width,height,scene;public long time;public byte[] gray,alpha;public float[] depth,boxes=new float[0];public float at(float x,float y){int xx=Math.max(0,Math.min(width-1,Math.round(x*(width-1)))),yy=Math.max(0,Math.min(height-1,Math.round(y*(height-1))));float[] a=new float[25];int n=0;for(int v=Math.max(0,yy-2);v<=Math.min(height-1,yy+2);v++)for(int u=Math.max(0,xx-2);u<=Math.min(width-1,xx+2);u++)a[n++]=depth[v*width+u];Arrays.sort(a,0,n);return a[n/2];}}
 public Feature feature(int i)throws Exception{Feature f=new Feature();f.time=times.get(i);f.scene=scenes.get(i);try(DataInputStream in=new DataInputStream(new BufferedInputStream(new FileInputStream(path(i,"track"))))){f.width=in.readInt();f.height=in.readInt();int n=f.width*f.height;f.gray=new byte[n];f.alpha=new byte[n];f.depth=new float[n];for(int j=0;j<n;j++){f.gray[j]=in.readByte();f.alpha[j]=in.readByte();f.depth[j]=in.readUnsignedShort()/65535f;}f.boxes=new float[in.readInt()];for(int j=0;j<f.boxes.length;j++)f.boxes[j]=in.readFloat();}return f;}
}
